# Any line starting with the # character is a comment line
#! Sample HF/cc-pVDZ H2O computation

memory 600 mb

molecule h2o {
  O
  H 1 0.96
  H 1 0.96 2 104.5
}

set basis cc-pVDZ
energy('scf')

#! Optimize H2O HF/cc-pVDZ


molecule h2o {
  O
  H 1 0.96
  H 1 0.96 2 104.5
}

set basis cc-pVDZ
optimize('scf')

#! Optimization followed by frequencies H2O HF/cc-pVDZ

molecule h2o {
  O
  H 1 0.96
  H 1 0.96 2 104.5
}

set basis cc-pVDZ
optimize('scf')
scf_e, scf_wfn = frequencies('scf', return_wfn=True, dertype=1)

#! Frequencies for H2O B3LYP/6-31G* at optimized geometry

molecule h2o {
  O
  H 1 0.96864
  H 1 0.96864 2 103.586
}

set basis 6-31G*
scf_e, scf_wfn = frequencies('b3lyp', return_wfn=True)
